pg=Path('C:/Program Files/PostgreSQL/18/bin')
def pgcmd(tool,db,*args):return [str(pg/(tool+'.exe')),'-h','127.0.0.1','-p','55432','-U','qa',*(['-d',db] if tool not in ['createdb','pg_restore','dropdb'] else []),*args]
def sql(db,s,name):
 f=out/(name+'.sql');f.write_text(s);return run(name,pgcmd('psql',db,'-v','ON_ERROR_STOP=1','-f',str(f)))
def rec(id,ok,what,detail):
 r=dict(id=id,status='PASS' if ok else 'FAIL',kind='BEHAVIOR',what=what,detail=detail,severity='' if ok else 'High')
 with open(out/'checks.jsonl','a') as f:f.write(json.dumps(r)+'\n')
 print(f'[{id}] {r["status"]} | {what} | {detail}')
