run('create-migrate',pgcmd('createdb','', 'aqualicious_migration'))
env['DATABASE_URL']='postgresql://qa@127.0.0.1:55432/aqualicious_migration?schema=public'
rc=run('migrate-deploy',['node',str(root/'backend/node_modules/prisma/build/index.js'),'migrate','deploy','--schema',str(root/'backend/prisma/schema.prisma')])
